face.layout_source:
// spectral-gate.face: the panel for tap/examples/spectral/spectral-gate.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/spectral-gate.face --meta <graph>.cragmeta

face "Spectral Gate" {
  row(gap = 10) {
    box "Gate" { knob.big "Threshold" (threshold) knob "Floor" (floor) }
    box "Time" { knob "Attack" (attack) knob "Release" (release) }
    box "Open" { bar "Open" (opened) }
    viz(grow = 1)
  }
}
